std::vector<std::pair<size_t, size_t>> collidingPairs;
const size_t n = boxes.size();

for (size_t i = 0; i < n; ++i) {
    for (size_t j = i + 1; j < n; ++j) {
        const BoundingBox3D& a = boxes[i];
        const BoundingBox3D& b = boxes[j];

        // Check for overlap in all three dimensions
        bool overlapX = (a.min.x <= b.max.x) && (a.max.x >= b.min.x);
        bool overlapY = (a.min.y <= b.max.y) && (a.max.y >= b.min.y);
        bool overlapZ = (a.min.z <= b.max.z) && (a.max.z >= b.min.z);

        if (overlapX && overlapY && overlapZ) {
            collidingPairs.emplace_back(i, j);
        }
    }
}

return collidingPairs;
